33	    background: #fff;
34	    color: inherit;
35	  }
36	  .search { display: block; width: 100%; margin-bottom: 12px; padding: 10px 12px; font: inherit; border: 1px solid #d6d3d1; border-radius: 8px; background: #fff; }
37	  .edit { flex: 1; min-width: 0; padding: 4px 8px; font: inherit; border: 1px solid #d6d3d1; border-radius: 6px; }
38	  input[type="text"]:focus, input[type="date"]:focus, select:focus, .search:focus, .edit:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
39	  button {
40	    font: inherit;
41	    border: 0;
42	    border-radius: 8px;
43	    cursor: pointer;
44	  }
45	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
46	  .add:hover { background: #1d4ed8; }
47	  ul { list-style: none; margin: 0; padding: 0; }
48	  li {
49	    display: flex;
50	    align-items: center;
51	    gap: 12px;
52	    padding: 10px 12px;
53	    margin-bottom: 8px;
54	    background: #fff;
55	    border: 1px solid #e7e5e4;
56	    border-radius: 8px;
57	  }
58	  .text { flex: 1; overflow-wrap: anywhere; }
59	  li input[type="checkbox"] { width: 18px; height: 18px; margin: 0; cursor: pointer; accent-color: #2563eb; }
60	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
61	  .due { font-size: 14px; color: #57534e; white-space: nowrap; }
62	  /* Priority is shown as a neutral text label only; no colour coding. */
63	  .priority { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 6px; border-radius: 4px; white-space: nowrap; background: #f5f5f4; color: #57534e; }
