66	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
67	  .filters button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
68	  .filters button:hover { background: #e7e5e4; }
69	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
70	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
