75	<body>
76	<main>
77	  <h1>Todos</h1>
78	  <form id="todo-form">
79	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
80	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
81	    <select data-testid="todo-priority" aria-label="Priority">
82	      <option value="low">Low</option>
83	      <option value="med" selected>Med</option>
84	      <option value="high">High</option>
85	    </select>
86	    <button type="submit" class="add" data-testid="todo-add">Add</button>
87	  </form>
88	  <input type="search" class="search" data-testid="search-input" placeholder="Search todos" aria-label="Search todos" autocomplete="off">
89	  <div class="filters" role="group" aria-label="Filter todos">
90	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
91	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
92	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
93	  </div>
94	  <ul data-testid="todo-list"></ul>
95	  <p class="empty" hidden>No todos yet.</p>
96	</main>
97	<script>
98	(function () {
99	  var STORAGE_KEY = 'todos';
100	  var form = document.getElementById('todo-form');
101	  var input = document.querySelector('[data-testid="todo-input"]');
102	  var dueInput = document.querySelector('[data-testid="todo-due"]');
103	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
104	  var list = document.querySelector('[data-testid="todo-list"]');
105	  var empty = document.querySelector('.empty');
106	  var filterButtons = document.querySelectorAll('[data-filter]');
107	  var searchInput = document.querySelector('[data-testid="search-input"]');
108	
109	  var PRIORITIES = ['low', 'med', 'high'];
110	  var DEFAULT_PRIORITY = 'med';
111	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
112	
113	  function normalizePriority(p) {
114	    return PRIORITIES.indexOf(p) !== -1 ? p : DEFAULT_PRIORITY;
115	  }
116	
117	  function load() {
118	    try {
119	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
120	      if (!Array.isArray(data)) return [];
121	      // Todos saved before priorities existed default to "med".
122	      data.forEach(function (t) { t.priority = normalizePriority(t.priority); });
123	      return data;
124	    } catch (e) {
125	      return [];
126	    }
127	  }
128	
129	  function save() {
130	    try {
131	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
132	    } catch (e) {
133	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
134	    }
135	  }
136	
137	  function makeId() {
138	    if (window.crypto && typeof crypto.randomUUID === 'function') {
139	      return crypto.randomUUID();
140	    }
141	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
142	  }
143	
144	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
145	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
146	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
147	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
148	
149	  function pad(n) { return (n < 10 ? '0' : '') + n; }
150	
151	  function todayLocal() {
152	    var d = new Date();
153	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
154	  }
155	
156	  // Overdue: due date strictly before today's local date. Due today is never overdue.
157	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
158	  function isOverdue(todo, today) {
159	    return !!todo.due && todo.due < today;
160	  }
161	
162	  function formatDue(due) {
163	    var parts = due.split('-');
164	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
165	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
166	  }
167	
168	  var todos = load();
169	  var filter = 'all';
170	  var query = '';
171	  var renderedDay = null;
172	  var editing = false;
173	
174	  // Ordering rule (project decision): active todos first, completed todos below.
175	  // Within each group, sort by priority (high, med, low); within the same
176	  // priority, keep insertion order (oldest first). `todos` is stored in
177	  // insertion order, and the index tiebreak keeps the sort stable.
178	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
179	
180	  function byPriority(group) {
181	    return group
182	      .map(function (t, i) { return { todo: t, index: i }; })
183	      .sort(function (a, b) {
184	        return (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) || (a.index - b.index);
185	      })
186	      .map(function (entry) { return entry.todo; });
187	  }
188	
189	  // Search: case-insensitive substring match on text, combined with the filter.
190	  function matchesQuery(todo) {
191	    return !query || todo.text.toLowerCase().indexOf(query) !== -1;
192	  }
193	
194	  function visibleTodos() {
195	    var matching = todos.filter(matchesQuery);
196	    var active = byPriority(matching.filter(function (t) { return !t.completed; }));
197	    var completed = byPriority(matching.filter(function (t) { return t.completed; }));
198	    if (filter === 'active') return active;
199	    if (filter === 'completed') return completed;
200	    return active.concat(completed);
201	  }
202	
203	  function render() {
204	    list.textContent = '';
205	    var visible = visibleTodos();
206	    var today = todayLocal();
207	    renderedDay = today;
208	    visible.forEach(function (todo) {
209	      var li = document.createElement('li');
210	      li.setAttribute('data-testid', 'todo-item');
211	      li.setAttribute('data-id', todo.id);
212	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
213	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
214	      li.setAttribute('data-priority', todo.priority);
215	
216	      var toggle = document.createElement('input');
217	      toggle.type = 'checkbox';
218	      toggle.checked = !!todo.completed;
219	      toggle.setAttribute('data-testid', 'todo-toggle');
220	      toggle.setAttribute('aria-label', 'Mark complete');
221	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
222	
223	      var text = document.createElement('span');
224	      text.className = 'text';
225	      text.setAttribute('data-testid', 'todo-text');
226	      text.textContent = todo.text;
227	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
228	
229	      var del = document.createElement('button');
230	      del.type = 'button';
231	      del.className = 'delete';
232	      del.setAttribute('data-testid', 'todo-delete');
233	      del.setAttribute('aria-label', 'Delete todo');
234	      del.textContent = 'Delete';
235	      del.addEventListener('click', function () { remove(todo.id); });
236	
237	      var priority = document.createElement('span');
238	      priority.className = 'priority';
239	      priority.setAttribute('data-testid', 'todo-priority-label');
240	      priority.textContent = PRIORITY_LABELS[todo.priority];
241	
242	      li.appendChild(toggle);
243	      li.appendChild(text);
244	      li.appendChild(priority);
245	      if (todo.due) {
246	        var due = document.createElement('time');
247	        due.className = 'due';
248	        due.setAttribute('data-testid', 'todo-due-date');
249	        due.setAttribute('datetime', todo.due);
250	        due.textContent = 'Due ' + formatDue(todo.due);
251	        li.appendChild(due);
252	      }
253	      li.appendChild(del);
254	      list.appendChild(li);
255	    });
256	    empty.textContent = todos.length === 0 ? 'No todos yet.'
257	      : query ? 'No todos match your search.'
258	      : filter === 'active' ? 'No active todos.'
259	      : 'No completed todos.';
260	    empty.hidden = visible.length > 0;
261	    filterButtons.forEach(function (btn) {
262	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
263	    });
264	  }
265	
266	  function add(text, due, priority) {
267	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
268	    save();
269	    render();
270	  }
271	
272	  // Inline editing: Enter or blur commits, Escape cancels.
273	  // Empty text on commit keeps the original text.
274	  function startEdit(textEl, todo) {
275	    if (editing) return;
276	    editing = true;
277	    var field = document.createElement('input');
278	    field.type = 'text';
279	    field.className = 'edit';
280	    field.setAttribute('data-testid', 'todo-edit-input');
281	    field.setAttribute('aria-label', 'Edit todo');
282	    field.value = todo.text;
283	    var finished = false;
284	
285	    function finish(commit) {
286	      if (finished) return;
287	      finished = true;
288	      editing = false;
289	      var value = field.value.trim();
290	      if (commit && value && value !== todo.text) {
291	        todo.text = value;
292	        save();
293	      }
294	      render();
295	    }
296	
297	    field.addEventListener('keydown', function (e) {
298	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
299	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
300	    });
301	    field.addEventListener('blur', function () { finish(true); });
302	
303	    textEl.replaceWith(field);
304	    field.focus();
305	    field.select();
306	  }
307	
308	  function remove(id) {
309	    todos = todos.filter(function (t) { return t.id !== id; });
310	    save();
311	    render();
312	  }
313	
314	  function setCompleted(id, completed) {
315	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
316	    save();
317	    render();
318	  }
319	
320	  filterButtons.forEach(function (btn) {
321	    btn.addEventListener('click', function () {
322	      filter = btn.getAttribute('data-filter');
323	      render();
324	    });
325	  });
326	
327	  searchInput.addEventListener('input', function () {
328	    query = searchInput.value.trim().toLowerCase();
329	    render();
330	  });
331	
332	  form.addEventListener('submit', function (e) {
333	    e.preventDefault();
334	    var text = input.value.trim();
335	    if (!text) return;
336	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
337	    add(text, due, priorityInput.value);
338	    input.value = '';
339	    dueInput.value = '';
340	    priorityInput.value = DEFAULT_PRIORITY;
341	    input.focus();
342	  });
343	
344	  render();
345	
346	  // Overdue status changes at local midnight; re-render when the day rolls over.
347	  setInterval(function () {
348	    // Skip while editing so a re-render does not discard the edit.
349	    if (!editing && todayLocal() !== renderedDay) render();
350	  }, 30000);
351	})();
352	</script>
353	</body>
354	</html>
